def gjennomsnitt(tall):
    if len(tall) == 0:
        return 0
    return sum(tall) / len(tall)

målinger = [23.5, 24.1, 22.8, 25.0, 23.7]
print(gjennomsnitt(målinger))  # 23.82

def finn_min_max(liste):
    if len(liste) == 0:
        return None, None

    minimum = liste[0]
    maksimum = liste[0]

    for element in liste:
        if element < minimum:
            minimum = element
        if element > maksimum:
            maksimum = element

    return minimum, maksimum

tall = [5, 2, 8, 1, 9, 3]
min_val, max_val = finn_min_max(tall)
print(f"Min: {min_val}, Max: {max_val}")  # Min: 1, Max: 9

